// SubtitleServiceHandler is an implementation of the mavio.acquisition.v1.SubtitleService service.
type SubtitleServiceHandler interface {
	// ListSubtitleProfiles lists the subtitle profiles by name.
	ListSubtitleProfiles(context.Context, *v1.ListSubtitleProfilesRequest) (*v1.ListSubtitleProfilesResponse, error)
	// CreateSubtitleProfile fails with ALREADY_EXISTS when a profile has the
	// name.
	CreateSubtitleProfile(context.Context, *v1.CreateSubtitleProfileRequest) (*v1.CreateSubtitleProfileResponse, error)
	UpdateSubtitleProfile(context.Context, *v1.UpdateSubtitleProfileRequest) (*v1.UpdateSubtitleProfileResponse, error)
	// DeleteSubtitleProfile deletes a profile and its assignments.
	DeleteSubtitleProfile(context.Context, *v1.DeleteSubtitleProfileRequest) (*v1.DeleteSubtitleProfileResponse, error)
	// AssignSubtitleProfile assigns a profile to a library, a movie or a
	// series, or removes the assignment; the movies and episodes it covers
	// are searched for the subtitles they now lack.
	AssignSubtitleProfile(context.Context, *v1.AssignSubtitleProfileRequest) (*v1.AssignSubtitleProfileResponse, error)
	GetSubtitleSettings(context.Context, *v1.GetSubtitleSettingsRequest) (*v1.GetSubtitleSettingsResponse, error)
	// UpdateSubtitleSettings replaces the settings and applies them at once.
	UpdateSubtitleSettings(context.Context, *v1.UpdateSubtitleSettingsRequest) (*v1.UpdateSubtitleSettingsResponse, error)
	// ListSubtitleProviders lists the providers of the subtitle provider
	// plugins, with their state.
	ListSubtitleProviders(context.Context, *v1.ListSubtitleProvidersRequest) (*v1.ListSubtitleProvidersResponse, error)
	// ListWantedSubtitles lists the movies or episodes lacking subtitles
	// their profiles want.
	ListWantedSubtitles(context.Context, *v1.ListWantedSubtitlesRequest) (*v1.ListWantedSubtitlesResponse, error)
	// SearchWantedSubtitles queues searches of the subtitles movies or
	// episodes lack, which download the best subtitles found.
	SearchWantedSubtitles(context.Context, *v1.SearchWantedSubtitlesRequest) (*v1.SearchWantedSubtitlesResponse, error)
	// UpgradeSubtitles queues a search for better subtitles than those
	// recently downloaded below their maximum score.
	UpgradeSubtitles(context.Context, *v1.UpgradeSubtitlesRequest) (*v1.UpgradeSubtitlesResponse, error)
	// GetItemSubtitles returns a movie's or episode's subtitles: its
	// profile, the subtitles it has and those it lacks.
	GetItemSubtitles(context.Context, *v1.GetItemSubtitlesRequest) (*v1.GetItemSubtitlesResponse, error)
	// SearchItemSubtitles asks the providers for a movie's or episode's
	// subtitles, scored, best first, without downloading any.
	SearchItemSubtitles(context.Context, *v1.SearchItemSubtitlesRequest) (*v1.SearchItemSubtitlesResponse, error)
	// DownloadItemSubtitle downloads a subtitle SearchItemSubtitles found
	// and saves it beside the video.
	DownloadItemSubtitle(context.Context, *v1.DownloadItemSubtitleRequest) (*v1.DownloadItemSubtitleResponse, error)
	// UploadSubtitle saves a subtitle file beside a movie's or episode's
	// video.
	UploadSubtitle(context.Context, *v1.UploadSubtitleRequest) (*v1.UploadSubtitleResponse, error)
	// ExtractSubtitle saves an embedded text subtitle stream of a movie's or
	// episode's video as a subtitle file, from playback's extraction cache.
	// Videos on cloud storage are refused (FAILED_PRECONDITION): their
	// embedded subtitles are never extracted.
	ExtractSubtitle(context.Context, *v1.ExtractSubtitleRequest) (*v1.ExtractSubtitleResponse, error)
	// DeleteSubtitle deletes a subtitle file of a movie or episode.
	DeleteSubtitle(context.Context, *v1.DeleteSubtitleRequest) (*v1.DeleteSubtitleResponse, error)
	// ModifySubtitle applies mods to a subtitle file of a movie or episode.
	ModifySubtitle(context.Context, *v1.ModifySubtitleRequest) (*v1.ModifySubtitleResponse, error)
	// SyncSubtitle synchronizes a subtitle file of a movie or episode with
	// its audio, or with another subtitle file; against the audio only on
	// local and network storage.
	SyncSubtitle(context.Context, *v1.SyncSubtitleRequest) (*v1.SyncSubtitleResponse, error)
	// BlocklistSubtitle blocklists the subtitle a history event downloaded,
	// deletes its file and searches for another.
	BlocklistSubtitle(context.Context, *v1.BlocklistSubtitleRequest) (*v1.BlocklistSubtitleResponse, error)
	ListSubtitleHistory(context.Context, *v1.ListSubtitleHistoryRequest) (*v1.ListSubtitleHistoryResponse, error)
	ListSubtitleBlocklist(context.Context, *v1.ListSubtitleBlocklistRequest) (*v1.ListSubtitleBlocklistResponse, error)
	// DeleteSubtitleBlocklist deletes entries, or every entry when ids is
	// empty and all is set.
	DeleteSubtitleBlocklist(context.Context, *v1.DeleteSubtitleBlocklistRequest) (*v1.DeleteSubtitleBlocklistResponse, error)
}

